});

test('empty range returns empty array', () => {
  expect(House.verses(3, 2)).toEqual([]);
});

test('verse 12 last line is house line', () => {
  const v = House.verse(12);
  expect(v[0]).toBe('This is the horse and the hound and the horn');
  expect(v[v.length - 1]).toBe('that lay in the house that Jack built.');
  expect(v).toHaveLength(12);
});
